// Tests for the items generated by `#![parser_cfg(expose_automaton)]`.

mod sum {
    use ferrolith::{Symbol, action::Action, grammar};

    #[allow(dead_code)]
    enum Tok {
        Num(i64),
        Plus,
    }

    grammar! {
        #![parser_cfg(expose_automaton)]

        type Token = Tok;

        #[left(Plus)]

        #[start]
        fn expr() -> i64 {
            (Num(n))                   => n,
            (l @ expr, Plus, r @ expr) => l + r,
        }
    }

    fn terminal(name: &str) -> usize {
        AUTOMATON
            .terminals
            .iter()
            .position(|t| *t == name)
            .unwrap_or_else(|| panic!("no terminal named {name}"))
    }

    fn nonterminal(name: &str) -> usize {
        AUTOMATON
            .nonterminals
            .iter()
            .position(|nt| *nt == name)
            .unwrap_or_else(|| panic!("no nonterminal named {name}"))
    }

    fn shift(state: usize, terminal: usize) -> usize {
        match action(state, terminal) {
            Action::Shift(s) => s,
            other => panic!("expected a shift, got {other:?}"),
        }
    }

    #[test]
    fn initial_state_shifts_num() {
        let s = shift(0, terminal("Num"));
        assert!(s < AUTOMATON.n_states);
        assert_eq!(
            AUTOMATON.states[s].incoming,
            Some(Symbol::Terminal(terminal("Num")))
        );
    }

    #[test]
    fn invalid_terminal_is_error() {
        assert_eq!(action(0, terminal("Plus")), Action::Error);
        assert_eq!(action(0, 0), Action::Error);
    }

    #[test]
    fn out_of_range_terminal_is_error() {
        assert_eq!(action(0, AUTOMATON.terminals.len()), Action::Error);
    }

    #[test]
    fn accepts_on_eof_after_expr() {
        let after_expr = goto(0, nonterminal("expr"));
        assert_eq!(
            AUTOMATON.states[after_expr].incoming,
            Some(Symbol::Nonterminal(nonterminal("expr")))
        );
        assert_eq!(action(after_expr, 0), Action::Accept);
        assert!(matches!(
            action(after_expr, terminal("Plus")),
            Action::Shift(_)
        ));
    }

    // `expr → expr Plus expr •` reduces on `Plus` (left associativity) and on EOF.
    // The parser reduces there by default, but `action` still gives the exact
    // LR(1) entries: `Num` is not a valid lookahead.
    #[test]
    fn exact_actions_in_default_reduction_state() {
        let plus = terminal("Plus");
        let after_expr = goto(0, nonterminal("expr"));
        let after_plus = shift(after_expr, plus);
        let after_rhs = goto(after_plus, nonterminal("expr"));

        let Action::Reduce(p) = action(after_rhs, plus) else {
            panic!("expected a reduce, got {:?}", action(after_rhs, plus));
        };
        let prod = &AUTOMATON.productions[p];
        assert_eq!(prod.lhs, nonterminal("expr"));
        assert_eq!(prod.rhs.len(), 3);

        assert_eq!(action(after_rhs, 0), Action::Reduce(p));
        assert_eq!(action(after_rhs, terminal("Num")), Action::Error);
        assert_eq!(default_reduction(after_rhs), Some(p));
    }

    #[test]
    fn exact_actions_after_num() {
        let after_num = shift(0, terminal("Num"));
        let Some(p) = default_reduction(after_num) else {
            panic!("expected a default reduction");
        };
        assert_eq!(AUTOMATON.productions[p].rhs.len(), 1);
        assert_eq!(action(after_num, terminal("Plus")), Action::Reduce(p));
        assert_eq!(action(after_num, 0), Action::Reduce(p));
        assert_eq!(action(after_num, terminal("Num")), Action::Error);
    }

    #[test]
    fn no_default_reduction_in_shifting_states() {
        assert_eq!(default_reduction(0), None);
        assert_eq!(default_reduction(goto(0, nonterminal("expr"))), None);
    }

    #[test]
    fn action_is_copy_and_debug() {
        let a = action(0, terminal("Num"));
        let b = a;
        assert_eq!(a, b);
        assert_eq!(format!("{:?}", Action::Shift(3)), "Shift(3)");
        assert_eq!(format!("{:?}", Action::Reduce(1)), "Reduce(1)");
        assert_eq!(format!("{:?}", Action::Accept), "Accept");
        assert_eq!(format!("{:?}", Action::Error), "Error");
    }
}

mod nonassoc {
    // A `nonassoc` tie is an explicit error entry: the state must not get a
    // default reduction, or the parser would reduce on the rejected token.
    use ferrolith::{action::Action, grammar};

    #[allow(dead_code)]
    enum Tok {
        Num(i64),
        Lt,
    }

    grammar! {
        #![parser_cfg(expose_automaton)]

        type Token = Tok;

        #[nonassoc(Lt)]

        #[start]
        fn expr() -> i64 {
            (Num(n))                 => n,
            (l @ expr, Lt, r @ expr) => (l < r) as i64,
        }
    }

    #[test]
    fn tie_state_has_no_default_reduction() {
        let lt = AUTOMATON.terminals.iter().position(|t| *t == "Lt").unwrap();
        let expr = AUTOMATON
            .nonterminals
            .iter()
            .position(|nt| *nt == "expr")
            .unwrap();

        let after_expr = goto(0, expr);
        let Action::Shift(after_lt) = action(after_expr, lt) else {
            panic!("expected a shift");
        };
        let after_rhs = goto(after_lt, expr);

        assert_eq!(action(after_rhs, lt), Action::Error);
        assert!(matches!(action(after_rhs, 0), Action::Reduce(_)));
        assert_eq!(default_reduction(after_rhs), None);
    }
}
